exports.seed = async function seedLingocafeBooks(knex) {
  await knex.transaction(async (trx) => {
    for (const book of books) {
      const { pages, questionnaireSql, ...bookRow } = book

      await trx.withSchema('lingocafe').table('books')
        .insert({
          ...bookRow,
          created_at: knex.fn.now(),
          updated_at: knex.fn.now()
        })
        .onConflict('id')
        .merge({
          lang: bookRow.lang,
          level: bookRow.level,
          title: bookRow.title,
          description: bookRow.description,
          author: bookRow.author,
          tags: bookRow.tags,
          project: bookRow.project,
          info: bookRow.info,
          published_at: bookRow.published_at,
          updated_at: knex.fn.now()
        })

      const existingPages = await trx.withSchema('lingocafe').table('books_pages')
        .select('book_id', 'id')
        .where({ book_id: book.id })
        .orderBy([{ column: 'book_id' }, { column: 'id' }])

      for (let index = 0; index < existingPages.length; index += 1) {
        const page = existingPages[index]

        await trx.withSchema('lingocafe').table('books_pages')
          .where({ book_id: page.book_id, id: page.id })
          .update({ position: -1000000 - index - 1 })
      }

      for (const page of pages) {
        await trx.withSchema('lingocafe').table('books_pages')
          .insert({
            book_id: book.id,
            ...page
          })
          .onConflict(['book_id', 'id'])
          .merge({
            position: page.position,
            kind: page.kind,
            prefix: page.prefix,
            title: page.title,
            summary: page.summary,
            content: page.content
          })
      }

      await trx.withSchema('lingocafe').table('books_pages')
        .where({ book_id: book.id })
        .whereNotIn('id', pages.map((page) => page.id))
        .del()

      if (questionnaireSql) {
        await trx.raw(questionnaireSql)
      }
    }
  })
}
